238	// CloseoutHandoff describes `pose close <scope> --apply` for a plan that has steps
239	// left, or nil when nothing is left to apply. The plan is the one the read-only
240	// planner computed; this function reads it and writes nothing.
241	func CloseoutHandoff(plan CloseoutPlan, target HandoffTarget) *OperationHandoff {
242		if plan.Terminal || plan.Scope == "" || len(plan.Blockers) > 0 {
243			return nil
244		}
245		if plan.ReadView != nil && plan.ReadView.Freshness == ReadViewFreshnessUnknown {
246			return nil // inputs not proven stable: the plan must be recomputed, not applied
247		}
248		pending, authority, needsReviewer := false, "maintainer", false
249		for _, step := range plan.Steps {
250			switch step.State {
251			case CloseoutStateBlocked:
252				return nil // a blocked step stops the apply: there is nothing to hand off
253			case CloseoutStatePending, CloseoutStateWaiting:
254				pending = true
255			}
256			if step.ID == CloseoutStepMechanical && (step.State == CloseoutStatePending || step.State == CloseoutStateWaiting) {
257				needsReviewer = true
258			}
259			if step.ID == CloseoutStepJudgment && step.State == CloseoutStateWaiting {
260				authority = "reviewer (a different-actor judgment is pending; the apply stops there)"
261			}
262		}
263		if !pending {
264			return nil
265		}
266		sum := sha256.Sum256([]byte("close\x00" + plan.Scope + "\x00" + plan.Digest))
267		handoff := &OperationHandoff{
268			Operation: "close",
269			RequestID: "hnd-" + hex.EncodeToString(sum[:8]),
270			Scope:     plan.Scope,
271			Phase:     "closeout",
272			Argv:      []string{"pose", "close", plan.Scope, "--apply", "--digest", plan.Digest},
273			Inputs: HandoffInputs{
274				PlanDigest: plan.Digest, SpecDigest: plan.Inputs.SpecDigest, Revision: plan.Inputs.Revision, PolicyDigest: plan.Inputs.PolicyDigest,
275			},
276			Target:             target,
277			RequiredAuthority:  authority,
278			ContextRequirement: "run it in the root of the target project, after `pose context --task " + plan.Scope + " --json` there shows the authority and revision this plan was computed under; `pose close --apply` takes no context flag, its binding is the plan digest, and this handoff carries no context",
279			Receipt:            "the CLI result of the apply, then `pose close " + plan.Scope + " --resume` or `pose_closeout_state` with include_plan to read the state again",
280			Invalidation:       "any change to the spec, the policy or the revision makes the plan digest stale; the index generation it was read at is recorded in inputs.generation for the performer to compare, and the apply does not check it; plan again instead of applying this handoff",
281		}
282		if needsReviewer {
283			// The mechanical attestation names the reviewing execution; `pose close --apply`
284			// stops at that step without --reviewer, so the handoff says it is owed.
285			handoff.RequiredInputs = append(handoff.RequiredInputs, "--reviewer <agent:id|human:id> (names the reviewing execution; the performer supplies it, the apply never invents it)")
286		}
287		if plan.ReadView != nil && len(plan.ReadView.Bindings) > 0 {
288			handoff.Inputs.Generation = plan.ReadView.Bindings[0].IndexGeneration
289			if handoff.Target.RootDigest == "" {
290				handoff.Target.RootDigest = plan.ReadView.Bindings[0].RootDigest
291			}
292		}
293		return handoff
294	}
