141	// runCLI executes a JSON-emitting, side-effect-free pose command; any
142	// non-zero exit is an error (these commands always succeed structurally).
143	func (s Store) runCLI(ctx context.Context, args []string) ([]byte, error) {
144		// A read-only command whose semantics the CLI package owns runs in process: one
145		// source of results, errors and coverage, and no second binary to start (spec
146		// pose-common-domain-and-cli-mcp-handoff R1).
147		if run, ok := inProcessCommand(args[0]); ok && inProcessRunsTheSpawnedEngine() {
148			return s.runInProcess(ctx, run, args)
149		}
150		cliSpawnAttempts.Add(1)
151		executable, err := s.nativeExecutablePath()
152		if err != nil {
153			return nil, err
154		}
155		ctx, cancel := context.WithTimeout(ctx, cliTimeout)
156		defer cancel()
157	
158		cmd := exec.CommandContext(ctx, executable, args...)
159		cmd.Dir = s.Root
160		cmd.Env = append(os.Environ(), "POSE_USAGE_SUPPRESS_CLI=1")
161		cmd.WaitDelay = cliWaitDelay
162		var stdout, stderr bytes.Buffer
163		cmd.Stdout, cmd.Stderr = &stdout, &stderr
164		if err := cmd.Run(); err != nil {
165			if cause := executionCause(ctx); cause != "" {
166				return nil, &GateExecutionError{Command: "pose " + strings.Join(args, " "), Cause: cause, PartialOutput: strings.TrimSpace(stdout.String() + stderr.String()), Cleanup: cliCleanupNote}
167			}
168			msg := strings.TrimSpace(stderr.String())
169			if msg == "" {
170				msg = strings.TrimSpace(stdout.String())
171			}
172			if msg == "" {
173				msg = err.Error()
174			}
175			return nil, fmt.Errorf("pose %s failed: %s", args[0], msg)
176		}
177		return stdout.Bytes(), nil
178	}
